    //
    // NULLABLE, deliberately — and NOT defaulted. "Never published" has to be representable and has to
    // be distinguishable from "published as issue 0", because that distinction is the entire input to
    // `bsc plan sync`: a NULL `gh_number` is what says an issue still needs creating. A `DEFAULT 0`
    // would make every pre-existing row claim to be issue #0 and the first sync would skip all of them.
    // The request lane gained a TIER it is addressed to (the director's upward channel) and the plan
    // item it concerns. An existing row means what it always meant — a worker asking its director —
    // which is exactly what the DEFAULT encodes, so no backfill is needed.
    let _ = conn.execute("ALTER TABLE requests ADD COLUMN target TEXT NOT NULL DEFAULT 'director'", []);
    let _ = conn.execute("ALTER TABLE requests ADD COLUMN ref_id TEXT NOT NULL DEFAULT ''", []);
    let _ = conn.execute("ALTER TABLE issues ADD COLUMN gh_number INTEGER", []);
    let _ = conn.execute("ALTER TABLE issues ADD COLUMN gh_node_id TEXT", []);
    let _ = conn.execute("ALTER TABLE issues ADD COLUMN synced_at INTEGER", []);
    // #146: an issue's own append-only observations, independent of whether it has a change record —
    // additive like the columns above, so an existing plan.db picks it up with no data loss.
    let _ = conn.execute("ALTER TABLE issues ADD COLUMN notes TEXT NOT NULL DEFAULT '[]'", []);
    // A change's recorded before/after MEASUREMENTS. Additive like everything above: every plan.db on
    // disk already has a `changes` table, and `CREATE TABLE IF NOT EXISTS` cannot add a column to one
    // that exists — so without this line the new column would appear only in stores created after it,
    // and every existing project would fail the read with "no such column".
    let _ = conn.execute("ALTER TABLE changes ADD COLUMN measures TEXT NOT NULL DEFAULT '[]'", []);
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn discovery_table_migrates_from_legacy_context_table() {
        // A pre-#1578 plan.db has the old `context` table; migrate() renames it in place so the
        // project's required-set carries forward (data preserved, no separate copy step).
        let conn = Connection::open_in_memory().unwrap();
        conn.execute_batch(
            "CREATE TABLE context (topic TEXT PRIMARY KEY, position INTEGER NOT NULL DEFAULT 0, \
             updated_at INTEGER NOT NULL DEFAULT 0); \
             INSERT INTO context (topic, position) VALUES ('goal', 1), ('scope', 2);",
        )
        .unwrap();
        migrate(&conn).unwrap();
        let topics: Vec<String> = conn
            .prepare("SELECT topic FROM discovery ORDER BY position")
            .unwrap()
            .query_map([], |r| r.get(0))
            .unwrap()
            .collect::<rusqlite::Result<_>>()
            .unwrap();
        assert_eq!(topics, vec!["goal".to_string(), "scope".to_string()]);
        // Idempotent: re-running migrate on the already-migrated db is a no-op (no `context` table).
        migrate(&conn).unwrap();
        let n: i64 = conn.query_row("SELECT COUNT(*) FROM discovery", [], |r| r.get(0)).unwrap();
        assert_eq!(n, 2);
    }

    /// #4080 — an EXISTING plan.db (a features table with no `requires`) gains the column in place,
    /// keeping its rows. Additive `ALTER TABLE … ADD COLUMN`, like `depends_on`/`phase` before it: the
    /// `CREATE TABLE IF NOT EXISTS` in the batch is a no-op for a db that already has the table, so
    /// without the ALTER an existing project would silently never see the new field.
    #[test]
    fn features_gains_requires_on_an_existing_db_without_losing_rows() {
        let conn = Connection::open_in_memory().unwrap();
        // A pre-#4080 features table — note: no `requires`.
        conn.execute_batch(
            "CREATE TABLE features (slug TEXT PRIMARY KEY, name TEXT NOT NULL, behavior TEXT, phase TEXT, \
             approach TEXT, data TEXT, stream TEXT, acceptance TEXT NOT NULL DEFAULT '[]', \
             tools TEXT NOT NULL DEFAULT '[]', depends_on TEXT NOT NULL DEFAULT '[]', \
             position INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0); \
             INSERT INTO features (slug, name, depends_on) VALUES ('kernel', 'Geometry kernel', '[\"maths\"]');",
        )
        .unwrap();
        migrate(&conn).unwrap();
        // The row survived, and the new column reads as the empty default rather than NULL.
        let (name, dep, req): (String, String, String) = conn
            .query_row("SELECT name, depends_on, requires FROM features WHERE slug = 'kernel'", [], |r| {
                Ok((r.get(0)?, r.get(1)?, r.get(2)?))
            })
            .unwrap();
        assert_eq!(name, "Geometry kernel");
        assert_eq!(dep, "[\"maths\"]", "existing data is untouched");
        assert_eq!(req, "[]", "the new column defaults to an empty list, never NULL");
        // Idempotent — a second migrate on the already-migrated db is a no-op, not an error.
        migrate(&conn).unwrap();
        let n: i64 = conn.query_row("SELECT COUNT(*) FROM features", [], |r| r.get(0)).unwrap();
        assert_eq!(n, 1);
    }

    /// An EXISTING plan.db gains the GitHub-identity columns in place. Every project on disk today has
    /// an `issues` table without them, and `CREATE TABLE IF NOT EXISTS` is a no-op for a table that
    /// already exists — so without the ALTERs those projects would never see the columns and every
    /// read would fail on the new `SELECT`.
    #[test]
    fn issues_gains_github_identity_on_an_existing_db_without_losing_rows() {
        let conn = Connection::open_in_memory().unwrap();
        // A pre-migration issues table — no gh_number / gh_node_id / synced_at.
        conn.execute_batch(
            "CREATE TABLE issues (ref TEXT PRIMARY KEY, title TEXT NOT NULL, phase TEXT, repo TEXT, \
             stream TEXT, parent TEXT, body TEXT, acceptance TEXT NOT NULL DEFAULT '[]', \
             owns TEXT NOT NULL DEFAULT '[]', depends_on TEXT NOT NULL DEFAULT '[]', \
             labels TEXT NOT NULL DEFAULT '[]', status TEXT NOT NULL DEFAULT 'open', \
             position INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0); \
             INSERT INTO issues (ref, title, status) VALUES ('invite-teammates', 'Invite teammates', 'complete');",
        )
        .unwrap();
        migrate(&conn).unwrap();

        // The row survived, and the identity reads as NULL — "never published", which is what makes the
        // first sync offer to create it. A DEFAULT 0 here would claim it is already issue #0.
        let (title, status, num): (String, String, Option<i64>) = conn
            .query_row("SELECT title, status, gh_number FROM issues WHERE ref = 'invite-teammates'", [], |r| {
                Ok((r.get(0)?, r.get(1)?, r.get(2)?))
            })
            .unwrap();
        assert_eq!(title, "Invite teammates");
        assert_eq!(status, "complete", "existing data is untouched");
        assert_eq!(num, None, "an unpublished row must be distinguishable from issue 0");

        // Idempotent — a second migrate on the already-migrated db is a no-op, not an error.
        migrate(&conn).unwrap();
        let n: i64 = conn.query_row("SELECT COUNT(*) FROM issues", [], |r| r.get(0)).unwrap();
        assert_eq!(n, 1);
    }

    /// THE MIGRATION THAT MATTERS: every plan.db on disk already has a `changes` table, and
    /// `CREATE TABLE IF NOT EXISTS` cannot add a column to one that exists. Without the `ALTER TABLE`,
    /// `measures` would appear only in stores created after it and every existing project would fail
    /// the read with "no such column: measures" — on the very first `bsc plan change get`.
    #[test]
    fn measures_is_added_to_a_changes_table_that_predates_it() {
        let conn = Connection::open_in_memory().unwrap();
        // The pre-`measures` shape, as a store written before this change carries it.
        conn.execute_batch(
            "CREATE TABLE changes (
                ref TEXT PRIMARY KEY, title TEXT NOT NULL DEFAULT '', body TEXT NOT NULL DEFAULT '',
                issues TEXT NOT NULL DEFAULT '[]', base TEXT NOT NULL DEFAULT 'develop',
                head_sha TEXT NOT NULL DEFAULT '', merge_sha TEXT NOT NULL DEFAULT '',
                status TEXT NOT NULL DEFAULT 'draft', gates TEXT NOT NULL DEFAULT '{}',
                notes TEXT NOT NULL DEFAULT '[]', reviewer TEXT NOT NULL DEFAULT '',
                reviewed_at INTEGER NOT NULL DEFAULT 0, gh_number INTEGER, gh_node_id TEXT,
                synced_at INTEGER, created_at INTEGER NOT NULL DEFAULT 0,
                updated_at INTEGER NOT NULL DEFAULT 0);
             INSERT INTO changes (ref, title) VALUES ('old-ref', 'written before measures existed');",
        )
        .unwrap();

        migrate(&conn).unwrap();

        // The column exists AND the pre-existing row survived with the documented default.
        let m: String =
            conn.query_row("SELECT measures FROM changes WHERE ref='old-ref'", [], |r| r.get(0)).unwrap();
        assert_eq!(m, "[]", "an existing change reads as having no measurements, not as broken");
